        { name = "Farewells", family = "Manners", lines = {
            { id = 3707787, text = "Speak! How do we leave this place?" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3707827, text = "We cannot leave these innocent souls alone to their fate." },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 546824, text = "We exist only to serve him." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 546825, text = "All is not lost. Not yet." },
            { id = 4323844, text = "As expected from you, Deathlord. Well struck." },
            { id = 1413953, text = "At last, the four horsemen shall have their leader." },
            { id = 1383547, text = "Before us this day stands our comrade in arms." },
            { id = 3728786, text = "Careful! The Jailer's eyes are everywhere!" },
            { id = 3730399, text = "Champion, preparations have been made." },
            { id = 3707824, text = "Could you make sense of what it said, Lord Admiral?" },
            { id = 3730400, text = "Deathlord, preparations have been made." },
            { id = 1413961, text = "Deathlord, we will begin at your command." },
            { id = 4324333, text = "Dreadlords, of course. Maw Walker, to me!" },
            { id = 3730258, text = "father" },
            { id = 546809, text = "For us there is no peace, no rest." },
            { id = 546828, text = "Harness your hate. Make it useful." },
            { id = 3671134, text = "Have been played to me! Tear this monstrosity down!" },
            { id = 546789, text = "His eyes are upon you at all times." },
            { id = 1512540, text = "Horsemen! Our destiny is at hand!" },
            { id = 1524546, text = "Horsemen! Our time has come!" },
            { id = 1411959, text = "Horsemen! We ride!" },
            { id = 3729153, text = "How long have you been trapped here?" },
            { id = 4324324, text = "Hurry!" },
            { id = 1413938, text = "If we do this, there will be a price to pay." },
            { id = 4324085, text = "It is done." },
            { id = 3670094, text = "It would be unwise to break the enchantment. Let's move along." },
            { id = 3670103, text = "Keep searching" },
            { id = 1383546, text = "Knights of the Ebon Blade, assemble as we honor one of our own." },
            { id = 3670190, text = "Knights, secure the cave! We'll hold off these fiends!" },
            { id = 3670093, text = "More of Lady Proudmoore's handiwork." },
            { id = 1512539, text = "No! I will not allow the Ebon Blade to fall!" },
            { id = 4324330, text = "No, we must not let her escape!" },
            { id = 3707786, text = "Our friend has something to share." },
            { id = 546857, text = "Ours is not to question, only to act!" },
            { id = 3729230, text = "Save your strength, Father. We'll have time to speak later." },
            { id = 4324327, text = "She's dominating that creature! Ebon Blade, stop her at once!" },
            { id = 1413936, text = "Should we go through with this? There will be no turning back." },
            { id = 3707819, text = "So there is a way out. Tell us where to find it." },
            { id = 3670142, text = "Something's flying at us from above!" },
            { id = 3733090, text = "Thank you for watching!" },
            { id = 3733142, text = "Thank you. Thank you." },
            { id = 3728783, text = "The brand holds the key." },
            { id = 1413951, text = "The Death Gate! Take it!" },
            { id = 546859, text = "The life we had before is meaningless." },
            { id = 1413948, text = "The time has come, Deathlord. Tyrion Fordring awaits." },
            { id = 3707826, text = "Then it seems our course is clear." },
            { id = 3729156, text = "Then show us a way to breach that tower!" },
            { id = 546861, text = "There he is!" },
            { id = 3729226, text = "This must be your missing Baron." },
            { id = 4323835, text = "Ugh! The power! Is this too much?" },
            { id = 3670104, text = "Up ahead, it's Lady Proudmoore." },
            { id = 3671131, text = "Use the helm while it's weakened!" },
            { id = 546783, text = "We are driven by a single purpose, retribution." },
            { id = 3670050, text = "We are establishing a forward position go make sure we hold it" },
            { id = 1413962, text = "We do what we must." },
            { id = 3670057, text = "We have done all we can here." },
            { id = 546865, text = "We know much about sacrifice." },
            { id = 1413959, text = "We must avoid direct confrontation if at all possible!" },
            { id = 3670056, text = "We rally up ahead. Go!" },
            { id = 4067551, text = "We will see it done." },
            { id = 3670192, text = "What did brawn mean by slip past them again escaped before" },
            { id = 1413952, text = "What is this?" },
            { id = 3670100, text = "Whatever is going on here, we don't want any part of it" },
            { id = 3729152, text = "Why would you aid us, Broker?" },
            { id = 1414947, text = "Without monsters, there can be no heroes." },
            { id = 3707785, text = "Your arrival is timely." },
            { id = 3671137, text = "You're coming with us!" },
        } },
    } },
