        { name = "Loyalty", family = "Manners", lines = {
            { id = 2399938, text = "Forgive me, Dark Lady." },
            { id = 2407037, text = "Of course, my lady." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2399810, text = "All things must end." },
            { id = 2399804, text = "Believe in nothing" },
            { id = 2444941, text = "CHA!" },
            { id = 2444942, text = "CHOO!" },
            { id = 2399930, text = "Death calls for you." },
            { id = 2399834, text = "Death claims us all." },
            { id = 2399828, text = "Death has come for you!" },
            { id = 2458436, text = "Doh!" },
            { id = 2458430, text = "D'oh! Ugh! Ugh!" },
            { id = 2458435, text = "Duh!" },
            { id = 2458424, text = "GASP" },
            { id = 2432654, text = "HA! UGH!" },
            { id = 2399941, text = "Her victory will come." },
            { id = 2399808, text = "Hope burns away to ashes." },
            { id = 2444901, text = "Huh?" },
            { id = 2444879, text = "Huh? Gah!" },
            { id = 2444885, text = "Hya!" },
            { id = 2432657, text = "Hyah!" },
            { id = 2399914, text = "In the end, death claims us all." },
            { id = 2407079, text = "It ran away last night. Did you see it?" },
            { id = 2407074, text = "Meet me at three corners. I have a plan." },
            { id = 2432673, text = "Mm-hmm." },
            { id = 2432689, text = "Mwah!" },
            { id = 2444960, text = "NAH!" },
            { id = 2399818, text = "Nothing's the same anymore." },
            { id = 2444886, text = "Nyeh!" },
            { id = 2399826, text = "Our victory is inevitable!" },
            { id = 2444940, text = "Pah!" },
            { id = 2399812, text = "Speak or go." },
            { id = 2407100, text = "Such a shame. I quite like spiders." },
            { id = 2458409, text = "Tch!" },
            { id = 2444904, text = "Thank you for watching!" },
            { id = 2399916, text = "The queen's enemies will fall." },
            { id = 2407099, text = "Their mother." },
            { id = 2399806, text = "There is only death and pain." },
            { id = 2407120, text = "Ugh, I'll never get used to the taste of this vile concoction." },
            { id = 2444884, text = "Vroom!" },
            { id = 2399920, text = "What do you seek?" },
            { id = 2407098, text = "Which means that our quarry must have also encountered..." },
            { id = 2407077, text = "Won't you please help us?" },
            { id = 2458412, text = "Yeah!" },
            { id = 2458432, text = "Yes!" },
            { id = 2407209, text = "You turned your back, on your duty to the Horde, Saurfang!" },
            { id = 2399820, text = "Your faith has blinded you." },
            { id = 2399934, text = "Your life is forfeit." },
        } },
    } },
