        { name = "Conversation", family = "Feelings", lines = {
            { id = 3637818, text = "A futile effort." },
            { id = 3380510, text = "A mere setback." },
            { id = 3380459, text = "An equivalent exchange." },
            { id = 3621445, text = "Another corpse to collect!" },
            { id = 3743333, text = "Enough! I yield. Name your terms." },
            { id = 3380457, text = "Everything has its price." },
            { id = 3380471, text = "Excellent! A new test subject!" },
            { id = 3380473, text = "Has your weapon found a target today?" },
            { id = 3380512, text = "How... disappointing." },
            { id = 3380511, text = "How...disappointing..." },
            { id = 3814130, text = "HUH-UH! Ugh, ugh..." },
            { id = 3621432, text = "I. Will. Return." },
            { id = 3380509, text = "I'm here to set back!" },
            { id = 3482842, text = "Let your fears consume you." },
            { id = 3380454, text = "May all weapons stay sharp." },
            { id = 3380439, text = "May your purpose be fulfilled" },
            { id = 3380453, text = "May your weapons stay sharp!" },
            { id = 3380469, text = "Must the rabble be so needy?" },
            { id = 3380479, text = "Some say it is gauche to barter, but I do so enjoy it." },
            { id = 3380443, text = "The Bulwark shall never fall!" },
            { id = 3482843, text = "There is no escape for you!" },
            { id = 3380477, text = "These are rare finds and worth the cost." },
            { id = 3380467, text = "This is hardly the time for idle conversation." },
            { id = 3607489, text = "Unbind me! What magic is this?" },
            { id = 3380449, text = "Victory at any cost!" },
            { id = 3380481, text = "War is not wage without supplies." },
            { id = 3380482, text = "War is not waged without supplies." },
            { id = 3380502, text = "We will meet again." },
            { id = 3621436, text = "What are you doing? This is treason?" },
            { id = 3380465, text = "What can you do for me?" },
            { id = 3743120, text = "What trickery is this?" },
            { id = 3743331, text = "Where am I who dares come to me?" },
            { id = 3380461, text = "Why have you interrupted me?" },
            { id = 3482844, text = "Wither in my grasp!" },
            { id = 3380483, text = "You know, only one of us has a phylactery!" },
            { id = 3482836, text = "Your demise was inevitable!" },
            { id = 3380489, text = "Your existence ends here!" },
