    { who = "Nathanos Blightcaller", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 1355061, text = "DO NOT DISAPPOINT THE BANCHIE QUEEN!" },
            { id = 1239115, text = "GRIFFIN'S INCOMING! MEND THAT CATAPULT!" },
            { id = 2001202, text = "LET'S MOVE!" },
            { id = 1803042, text = "OVER HERE!" },
            { id = 1803043, text = "THIS WAY!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 1239135, text = "Ha! There you are!" },
            { id = 2433416, text = "Hehehe, you are too late. Behold!" },
            { id = 3049397, text = "Meet me on the wall when you are done." },
            { id = 2054296, text = "Vengeance, contempt, call it what you will." },
            { id = 2433417, text = "Which you shall pay dearly for that let's move" },
            { id = 2433414, text = "You cannot hide from me forever, elf!" },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 2114274, text = "I beg your pardon?" },
            { id = 2001185, text = "I have a potion for each of you. Don't drink it just yet." },
            { id = 2434468, text = "I knew you didn't have it in you." },
            { id = 2433906, text = "I need this blockade broken, and these docks secured!" },
            { id = 2001147, text = "I obey my queen." },
            { id = 3596201, text = "I see you cowering there!" },
            { id = 1363223, text = "I shall wear your entrails as a necklace!" },
            { id = 2029298, text = "My queen." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 2433639, text = "As if those primitive glaives could intimidate me, fools!" },
            { id = 1243494, text = "Fooled dwarf. Deliver his head to the foothold." },
            { id = 3583493, text = "My hounds will make a meal of your pitiful flesh!" },
            { id = 3596192, text = "Stand and face me, cowards!" },
            { id = 1243498, text = "The bold fools are boarding my ship! Come on!" },
        } },
        { name = "Orders", family = "Orders and warnings", lines = {
            { id = 2435312, text = "A powerful adversary has been sighted nearby. Take it down!" },
            { id = 3049398, text = "and be quick about it." },
            { id = 3596195, text = "Back into the fray with you!" },
            { id = 1363220, text = "Do not test me." },
            { id = 2016059, text = "Find work. Our operations can move ahead as planned." },
            { id = 1800562, text = "Fire! Don't leave one of those bastards breathing!" },
            { id = 1363214, text = "Get moving!" },
            { id = 2433730, text = "Get the Bachelorette. Cut down anything in your path." },
            { id = 2433731, text = "Get us to the shore, now!" },
            { id = 2433727, text = "Hold the line! Our allies will do what needs to be done!" },
            { id = 2433645, text = "Leave nothing alive!" },
            { id = 2021980, text = "Let's move out!" },
            { id = 2114311, text = "Protect our extractor! We need that azerite!" },
            { id = 3596198, text = "Rise! Attack!" },
            { id = 2001201, text = "Stop gawking and break through that ice!" },
            { id = 1239133, text = "Stop holding back, old man! Show us the real you!" },
            { id = 2433724, text = "Take out those glaive throwers!" },
            { id = 1800564, text = "Take them down! You do not want to disappoint your Warchief!" },
        } },
        { name = "Victory", family = "Fighting", lines = {
            { id = 3583487, text = "Alliance horde? Pathetic, the lot of you!" },
            { id = 2433728, text = "Another one down! Allies, with me!" },
            { id = 2433411, text = "You are nothing. Raise them!" },
        } },
        { name = "Greetings", family = "Manners", lines = {
            { id = 2434459, text = "Ah, the hero has arrived. Good, we have work to do." },
        } },
        { name = "Farewells", family = "Manners", lines = {
            { id = 1355059, text = "Good luck with the trials, Shiro." },
            { id = 2001197, text = "I'll find you. Good luck." },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 2433646, text = "Blight it all, from here to the shoreline." },
            { id = 2433644, text = "Deploy the blight" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 2001203, text = "Already taken care of. Observe." },
            { id = 2433059, text = "Another victory for the Horde!" },
            { id = 1800575, text = "Champion, the Dark Lady instructs you to meet me in Orgrimmar." },
            { id = 1363212, text = "for the Dark Lady." },
            { id = 2433734, text = "Make your way to the islet and finish this, for the Dark Lady." },
            { id = 2433642, text = "No. Forgive me, my queen." },
            { id = 3583496, text = "Of course, my Queen. We will not disappoint you." },
            { id = 2435313, text = "One more body for the Dark Lady's army." },
            { id = 1239129, text = "Slay them all for the Dark Lady!" },
            { id = 2016062, text = "The Dark Lady chooses her champions well." },
            { id = 2001211, text = "The Dark Lady will be pleased." },
            { id = 2001175, text = "The Dark Lady will surely appreciate your service." },
            { id = 2001190, text = "We will not fail you, my queen." },
            { id = 2029301, text = "We will not fail you. Safe journey, my lady." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 2435314, text = "A blow well struck, the Horde triumphs once again." },
            { id = 2433057, text = "A dangerous foe is lurking in our midst. Show them no mercy." },
            { id = 2435310, text = "A new threat emerges. Give no quarter!" },
            { id = 1239113, text = "A single gunship? Are they insane?" },
            { id = 1800559, text = "Almost there! Do not relent! More Azerite!" },
            { id = 1800557, text = "An acceptable first effort, but we need more Azerite!" },
            { id = 2029300, text = "As you command, Warchief." },
            { id = 1239117, text = "Beasts all over the ship! Put them down!" },
            { id = 2433723, text = "By all means, take your time. I'm sure the Alliance will wait." },
            { id = 2433058, text = "Call in the Valkyr. This one will make a useful ally." },
            { id = 2001208, text = "Certainly wasn't a quiet operation, but it was effective." },
            { id = 2433766, text = "Darkshore has been retaken by the Horde, as it should be." },
            { id = 2433643, text = "Death can never truly be defeated." },
            { id = 2433767, text = "Death comes for us all!" },
            { id = 2433412, text = "Enough! Any last words, priestess?" },
            { id = 2433778, text = "Enough! The Warchief has arrived." },
            { id = 3583491, text = "Even that decrepit Saurfang put up a better fight than this!" },
            { id = 1239119, text = "Filthy wargen, a beast in a hat is still a beast." },
            { id = 2001184, text = "Good. We're all here." },
            { id = 1800558, text = "Ha! Snatched it out of the Alliance's hands! Well struck!" },
            { id = 2001142, text = "Have faith in the Warchief's strategy, Theron!" },
            { id = 2001188, text = "Heh, this does not concern you." },
            { id = 2001148, text = "Heroes, follow me!" },
            { id = 2433797, text = "Hmph. I see might here. Let's move!" },
            { id = 2001233, text = "Hmph. Speaker of the Horde." },
            { id = 1363222, text = "How DARE you!" },
            { id = 2433729, text = "How rich! The feathered elf thinks he can stop us!" },
            { id = 1363193, text = "Hwah! Ugh..." },
            { id = 1363224, text = "If you run now, you may live." },
            { id = 2001183, text = "I'll circle above and call out anything that looks interesting." },
            { id = 2001154, text = "It is better if she tells you herself. Now go!" },
            { id = 2001143, text = "It is you who is outnumbered now." },
            { id = 2433640, text = "I've arranged a little reunion for you. Dark Rangers, attack!" },
            { id = 2001177, text = "Lady Ashvane has a kraken?" },
            { id = 2433733, text = "Look around you, elf. Nature has already lost." },
            { id = 1803038, text = "Look out!" },
            { id = 2001141, text = "Lordaeron belongs to the Forsaken! Do not back down!" },
            { id = 2433674, text = "Lordinelle is under our control. Defend those catapults!" },
            { id = 1363217, text = "Make it quick!" },
            { id = 2001215, text = "Make your way to the top floor, where the Overseer can be found." },
            { id = 1363215, text = "Make yourself useful." },
            { id = 1363210, text = "MWAH!" },
            { id = 2433638, text = "No ragtag band of elves is going to retake these lands." },
            { id = 1239069, text = "No sign of Sylvanas in the hills. What have we here?" },
            { id = 2001204, text = "No, but I think I know why. Look!" },
            { id = 2001187, text = "Not even I know its nature yet." },
            { id = 1239073, text = "NOW!" },
            { id = 2001180, text = "Oh my, looks as if Boralus is already in its death throes." },
            { id = 2433056, text = "Our scouts have spotted a powerful threat nearby. Take it out." },
            { id = 2001213, text = "Our target is being held within toll de Gaulle." },
            { id = 1363219, text = "out with it" },
            { id = 2433798, text = "Proudmoore. Oh, I am going to enjoy seeing you fall." },
            { id = 1363187, text = "RAWR!" },
            { id = 2001205, text = "Respectfully, we have a boat to catch." },
            { id = 3049400, text = "Safe journey, my love." },
            { id = 2921742, text = "So, Lor'themar shows his true colors at last." },
            { id = 2001158, text = "Soldiers, fall into position! The Alliance approaches!" },
            { id = 2001245, text = "That should remind them of their place." },
            { id = 1239071, text = "That's one of hers, all right." },
            { id = 2433725, text = "The battlefield awaits, this way!" },
            { id = 2016057, text = "The Warchief will be pleased by your success." },
            { id = 2001235, text = "The Warchief's will be done." },
            { id = 2001234, text = "The Zandalari do not seem to like me much." },
            { id = 2001229, text = "The Zandalari fleet must join the Horde. Make it happen." },
            { id = 2001226, text = "These feathers will provide for our rangers for some time." },
            { id = 2001173, text = "This beast is using weapons empowered with Azerite." },
            { id = 2001222, text = "This was just a replica. Let us not speak of this again." },
            { id = 2433722, text = "This will be our base. Bashar Laran belongs to the Horde." },
            { id = 2001218, text = "This will do. The Warchief sends her regards." },
            { id = 2435315, text = "Thus will be the fate of all enemies of the Horde." },
            { id = 2001220, text = "Truly, no creature stands in your way for long." },
            { id = 1363213, text = "Try not to get yourself killed." },
            { id = 2001145, text = "Victory for the Forsaken!" },
            { id = 2001236, text = "We need that Zandalari fleet." },
            { id = 2001162, text = "We will wreak havoc on the Alliance with these munitions!" },
            { id = 2435309, text = "Well done. Just make sure they stay dead this time." },
            { id = 2114280, text = "Well done. Our foes will be ill-equipped to defy us." },
            { id = 2001198, text = "Well, this is a fine mess we're in!" },
            { id = 2434465, text = "Well, this is inconvenient. Protect the Valkyr!" },
            { id = 2434467, text = "What are you waiting for? Finish her!" },
            { id = 2434462, text = "What have you dragged along with you?" },
            { id = 1363218, text = "What is it?" },
            { id = 2433415, text = "WHAT?!" },
            { id = 2001152, text = "With us out in the open, we will outnumber them ten to one." },
            { id = 1243496, text = "Yes, of course. Come along, hero." },
            { id = 1239131, text = "You call us monsters? How rich!" },
            { id = 2433794, text = "You heard her! Keep moving!" },
            { id = 1245023, text = "You there! I require a moment of your time." },
            { id = 1803041, text = "You! Over here!" },
            { id = 2433800, text = "You! Tell us what happened here. Now!" },
            { id = 2001144, text = "Your time is up, King Anduin!" },
        } },
    } },
