        { name = "Dark magic", family = "Fighting", lines = {
            { id = 3380686, text = "Ah, the sweet aroma of decay." },
            { id = 3380685, text = "Ahh, the sweet aroma of decay." },
            { id = 3380717, text = "Blood and bone, flesh and stone!" },
            { id = 3380713, text = "Face the power of necromancy!" },
            { id = 4035289, text = "Fall and rise once more." },
            { id = 3380665, text = "For the Margrave and Maldraxxus." },
            { id = 3380689, text = "Have you been keeping up with your rituals?" },
