            { id = 3738690, text = "The eyes will be purged from Maldraxxus!" },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 3637837, text = "Aha! So you did botch the procedure!" },
            { id = 4035291, text = "Another minion for the banished one." },
            { id = 3380730, text = "Another soldier falls." },
            { id = 3735690, text = "As you command, master, it will be done at once." },
            { id = 3380699, text = "Better me than a broker." },
            { id = 3738125, text = "Buttons!" },
            { id = 4035298, text = "He. Will. Reveal." },
            { id = 556304, text = "How dare you come here!" },
            { id = 3380703, text = "How do you feel about repossessed goods?" },
            { id = 4188359, text = "How many shots will it take to destroy this car?" },
            { id = 3735688, text = "It was nowhere to be found, Master." },
            { id = 3735331, text = "Kael'thas Zod will find you! Kael'thas Sunstrider!" },
            { id = 4188365, text = "Let it go!" },
            { id = 3380671, text = "May your path keep you from the Maw." },
            { id = 3380672, text = "May your path keep you from them all." },
            { id = 3738672, text = "Mephiles! Mephiles knows everything!" },
            { id = 3738348, text = "Minions, time to feed!" },
            { id = 3738698, text = "More orders? What now?" },
            { id = 3738147, text = "More pots for the constructs!" },
            { id = 4035292, text = "Oblivion beckons." },
            { id = 4035296, text = "Only you, darkness." },
            { id = 3738233, text = "Our master will not tolerate failure!" },
            { id = 556302, text = "Outsiders are forbidden!" },
            { id = 3735335, text = "Please, have mercy." },
            { id = 3380677, text = "Possessions are only temporary." },
            { id = 3380669, text = "Primus favor you." },
            { id = 3380679, text = "Primus's fortune be upon you." },
            { id = 3564363, text = "Prove it up!" },
            { id = 3380698, text = "Regents. Materials. Scrolls. All for sale." },
            { id = 3380728, text = "Still, more to learn." },
            { id = 3738699, text = "Summon Motanis in this drought? Preposterous!" },
            { id = 3735322, text = "Tell the who? Never heard of him." },
            { id = 3607484, text = "That would please the Arch-Lech greatly." },
            { id = 4075366, text = "The Archives laid bare." },
            { id = 3738238, text = "The Arch-Lich will never fall!" },
            { id = 3607486, text = "The Archlich will not allow her failure." },
            { id = 3380673, text = "The cycle continues." },
            { id = 3380695, text = "The cycle has brought you to me." },
            { id = 3380732, text = "The cycle takes me." },
            { id = 3607482, text = "The death of the master surely means..." },
            { id = 3738169, text = "The house... will not fall." },
            { id = 3738678, text = "The Kyrian will fall!" },
            { id = 3738681, text = "The Maw Walker is here! Inform Tel'thuzad at once!" },
            { id = 4035295, text = "The Maw will claim you." },
            { id = 3380734, text = "The Primus has left us." },
            { id = 3380731, text = "The...cycle...takes me." },
            { id = 3738121, text = "There it is!" },
            { id = 3738165, text = "They will make use of me." },
            { id = 556303, text = "This is sacred ground!" },
            { id = 3738173, text = "This was not my fate." },
            { id = 3380701, text = "This will support my future endeavors." },
            { id = 3380661, text = "To seek, to strive, to emerge victorious." },
            { id = 3380663, text = "Trust in the cycle." },
            { id = 3738693, text = "We will choke the skies!" },
            { id = 3738235, text = "We will execute the will of the Arch-Lich!" },
            { id = 3380681, text = "Whatever you need, I am sure I can dig up." },
            { id = 3380682, text = "Whatever you need, I'm sure I can dig up." },
            { id = 3738167, text = "Who will finish my research?" },
            { id = 4035297, text = "Wither into dust." },
