    { who = "Sylvanas Windrunner", groups = {
        { name = "Battle cries", family = "Fighting", lines = {
            { id = 2002754, text = "DESTROY THEM!" },
            { id = 4082343, text = "FALL HERO!" },
            { id = 1406282, text = "FOR THE HORDE!" },
            { id = 4081139, text = "HEAR THE SOUND OF SUFFERING!" },
            { id = 4081776, text = "I NEVER MISS!" },
            { id = 2002764, text = "KEEP MOVING!" },
            { id = 4081773, text = "NO MERCY!" },
            { id = 4081140, text = "NOTHING ESCAPES MY WRATH!" },
            { id = 4081775, text = "TO THE DEATH!" },
            { id = 561271, text = "WE ARE THE FORSAKEN!" },
            { id = 4082345, text = "YOU ALWAYS WERE WEAK!" },
        } },
        { name = "Attack grunts", family = "Fighting", lines = {
            { id = 561309, text = "AH!" },
            { id = 561323, text = "EH!" },
            { id = 561302, text = "HA!" },
            { id = 561299, text = "UGH!" },
        } },
        { name = "Threats", family = "Menace", lines = {
            { id = 2002773, text = "Ah, there you are. I was beginning to wonder." },
            { id = 1248590, text = "Gul'dan! You will pay for this!" },
            { id = 3587740, text = "I am certain you won't." },
            { id = 4082358, text = "I shattered your throne! Now I'll break you!" },
            { id = 1801002, text = "I trust you will not waste my time." },
            { id = 4081159, text = "In death you will serve!" },
            { id = 561219, text = "In life, we suffered unspeakable tragedies." },
            { id = 3587734, text = "It seems you have an eye for talent, Warlord Grimax." },
            { id = 1244139, text = "No matter. Soon you will witness the birth of a new age." },
            { id = 2002781, text = "Oh, I know you won't." },
            { id = 2002770, text = "Or perhaps, you will have a chance to say hello to your son." },
            { id = 1801007, text = "Serve me well, and you will be rewarded." },
            { id = 4081163, text = "Suffer my wrath!" },
            { id = 4080416, text = "Surrender your sigil, or the wildseeds will perish." },
            { id = 2062637, text = "Take their hope and you will claim victory for the Horde!" },
            { id = 2108665, text = "Then it is decided. Saurfang, Nathanos, you will leave at once." },
            { id = 4324115, text = "This is not the end of your suffering, but it is a step forward." },
            { id = 3084085, text = "When next you see me, you will understand." },
            { id = 2002734, text = "You are the right arrow for the shot, champion." },
            { id = 4081162, text = "You are unfit to stand against me!" },
            { id = 4080413, text = "You are wise to show restraint, but it changes nothing." },
            { id = 4082359, text = "You will pay! All of you will pay!" },
            { id = 4496031, text = "Your kingdom and your friends are awaiting your return." },
        } },
        { name = "Boasts", family = "Menace", lines = {
            { id = 4081772, text = "I always hit my mark." },
            { id = 2565373, text = "I am Sylvanas Windrunner, and I approve this message." },
            { id = 4327507, text = "I don't remember the exact moment I rested control." },
            { id = 4324488, text = "I expect no less." },
            { id = 2407035, text = "I expect you to find him before they do." },
            { id = 897338, text = "I feel better already." },
            { id = 2108675, text = "I have a crow to hunt." },
            { id = 561301, text = "I have no time for games." },
            { id = 561232, text = "I have not always been the Banshee Queen." },
            { id = 2736326, text = "I have troubling news." },
            { id = 4324516, text = "I know, sisters, but judgment comes." },
            { id = 2002732, text = "I never doubted you for a moment." },
            { id = 2002774, text = "I require the services of one whom I can trust, completely." },
            { id = 897360, text = "I see the Dragonmaw have thrown in their lot with Garrosh." },
            { id = 4383680, text = "I submit to the judgment." },
            { id = 4496037, text = "I thought you believed in free will." },
            { id = 3084076, text = "I understand the cruelty of fate better than anyone." },
            { id = 4075660, text = "I will deal with the invading forces atop Torghast." },
            { id = 4322887, text = "I will face whatever comes." },
            { id = 561267, text = "I will never allow it! Never!" },
            { id = 4322893, text = "I will never serve." },
            { id = 897336, text = "I will not fall. Not here, not now." },
            { id = 897362, text = "My arrows alone cannot bring that monstrosity down." },
            { id = 3052353, text = "My Dark Rangers have vital information to share with you." },
            { id = 2108679, text = "My victory was inevitable. He was merely wasting my time." },
        } },
        { name = "Mockery", family = "Menace", lines = {
            { id = 4093247, text = "Fools! You fight a battle you cannot win!" },
            { id = 4080417, text = "Pitiful fey! You've already lost!" },
            { id = 2108689, text = "Ugh, fools! At least now we know how dangerous the wisps can be." },
            { id = 561220, text = "We are a shell in a coward's spine." },
