            { id = 2028796, text = "Farewell, Nathanos." },
            { id = 4322890, text = "Farewell." },
            { id = 1248676, text = "Good luck, Varian." },
        } },
        { name = "Despair", family = "Hurt and dying", lines = {
            { id = 4081141, text = "All hope is lost!" },
            { id = 4322889, text = "We are more than slaves to our torments." },
            { id = 561327, text = "What are we if not slaves to this torment?" },
        } },
        { name = "Dark magic", family = "Fighting", lines = {
            { id = 561233, text = "Children of the Grave, heed my call!" },
            { id = 3049145, text = "Countless souls have been fed to the hungering darkness." },
            { id = 4081170, text = "Do you fear the shadows?" },
            { id = 2002751, text = "Prepare the blight! Let it rain down upon their armies!" },
            { id = 4081171, text = "Shadows draw near." },
            { id = 573178, text = "Watch, heathens, as death surrounds you!" },
            { id = 561346, text = "What joy is there in this curse!" },
        } },
        { name = "Loyalty", family = "Manners", lines = {
            { id = 1800998, text = "All will serve the Horde in time." },
            { id = 4081135, text = "Heed the call of the Banshee Queen!" },
            { id = 3084082, text = "In the end, he too will serve death." },
            { id = 561239, text = "Isn't it obvious, Warchief? I serve the Horde." },
            { id = 561249, text = "Now the Lich King is dead, and we have returned." },
            { id = 1800995, text = "Serve the Horde, serve me." },
            { id = 1248608, text = "The armies of Azeroth will triumph this day, together!" },
            { id = 1801006, text = "There will be a new future for the Horde." },
            { id = 2002777, text = "To win this war, the Horde needs allies." },
            { id = 561297, text = "We are the Forsaken. We will slaughter anyone who stands in our way." },
            { id = 561265, text = "We are the instruments of the Unyielding Aya!" },
            { id = 2002726, text = "We struck a significant blow to their reserves, Hero. Well done." },
        } },
        { name = "Conversation", family = "Feelings", lines = {
            { id = 897368, text = "A hail of death approaches. Bring them to their fate." },
            { id = 561255, text = "Agatha, show the Warchief!" },
            { id = 1248662, text = "All yours, Alliance!" },
            { id = 2002746, text = "Alright, that's enough. Let's save some for the grand finale." },
            { id = 2429534, text = "And death is mine to master." },
            { id = 4330822, text = "And I do not expect your mercy." },
            { id = 561244, text = "And my people have not always been the Forsaken." },
            { id = 4509388, text = "And one." },
            { id = 573174, text = "And so ends your story." },
            { id = 897344, text = "And there goes the other one." },
            { id = 561251, text = "And they are part of the reason that I asked to see you." },
            { id = 4329613, text = "Anduin may be the key, if we can save him from..." },
            { id = 2068754, text = "Another victory." },
            { id = 1248630, text = "Another wave incoming!" },
            { id = 1248910, text = "Anyone have any ideas how we're going to get across this thing?" },
            { id = 2002780, text = "Are you up to the task?" },
            { id = 561262, text = "As a race, we've forsaken our unable to procreate." },
            { id = 3166452, text = "at present." },
            { id = 4093250, text = "Azeroth's champions, you've arrived at last." },
            { id = 2002755, text = "Bane, pull them back!" },
            { id = 2120268, text = "Brace yourselves!" },
            { id = 4326948, text = "Break his hold and win! The strength lies within you!" },
            { id = 2736328, text = "But Derek Proudmoore didn't flee to Kul Tiras by himself." },
            { id = 2002776, text = "But I understand discretion very well." },
            { id = 4327512, text = "But there would be no justice that day." },
            { id = 1406277, text = "Champion, come forward." },
            { id = 2002782, text = "Champion, the Horde is now at open war with the Alliance." },
            { id = 2575607, text = "Congratulations, your majesty." },
            { id = 1248660, text = "Consider your job done then, Rin." },
            { id = 1248914, text = "Convenient." },
            { id = 573176, text = "Cry Havoc!" },
            { id = 2002736, text = "Cut the rose before it can sprout thorns, I always say." },
            { id = 4081142, text = "darkness take you" },
            { id = 4081137, text = "Death awaits you!" },
            { id = 4081160, text = "Death bends to my will!" },
            { id = 4324002, text = "Death would be a merciful end, Tyrande." },
            { id = 2429529, text = "Derek Proudmoore was a hero to the Koltirens." },
            { id = 2002749, text = "Enough meddling! The towers! The towers!" },
            { id = 3049149, text = "Enough reflection. There are preparations to be made." },
            { id = 2921251, text = "Enough!" },
            { id = 4081167, text = "Enough! Your resistance ends here!" },
            { id = 2575614, text = "equals" },
            { id = 1248713, text = "Everyone, pull back to me! We make our stand here!" },
            { id = 4081164, text = "Fall into oblivion!" },
            { id = 4082344, text = "Feel for the more!" },
            { id = 4327513, text = "for anyone." },
            { id = 2407038, text = "Good hunting, champion." },
            { id = 1245021, text = "Good. Send a bat. Tell them we are leaving shortly." },
            { id = 2764309, text = "He had help, didn't he?" },
            { id = 4081136, text = "Hear my cry and despair!" },
            { id = 4324003, text = "However long it takes." },
            { id = 897340, text = "Huh, a bold move." },
            { id = 897350, text = "Huh, if he's not dead." },
            { id = 2464036, text = "Huh?" },
            { id = 1244143, text = "If you ever make it out of here, that is." },
            { id = 561246, text = "In death, they were reborn as mindless undead." },
            { id = 1800915, text = "Indeed, First Arcanist." },
            { id = 2029156, text = "Is everything in order?" },
            { id = 2002756, text = "Is the Undercity evacuated?" },
            { id = 2764308, text = "It seems there are traitors in our midst." },
            { id = 4332018, text = "It shall be done." },
            { id = 561223, text = "It was when Arthas was at his weakest that I struck." },
            { id = 1248830, text = "It's about time you showed up." },
            { id = 1248699, text = "Less chatting, Rin! Kill him already!" },
            { id = 561322, text = "Let none survive." },
            { id = 4324121, text = "Let us be done with this." },
            { id = 561272, text = "Lordaeron belongs to the Forsaken. Always and forever." },
            { id = 2108690, text = "Malfurion! How gracious of you to join us!" },
            { id = 561280, text = "May my aim be true." },
            { id = 2002760, text = "Meet with Lothimar! Quickly! Do not fail me, Nathanos!" },
            { id = 1248618, text = "Monsters from the Fel Fire, hard forces, be ready!" },
            { id = 2736327, text = "Most of you need fear nothing." },
            { id = 4496035, text = "Must you bear that weight?" },
            { id = 3587739, text = "Nathanos, brief our new arrival on the mission at hand." },
            { id = 2976145, text = "Nathanos, the next phase of our campaign is at hand." },
            { id = 4496036, text = "No choice?" },
            { id = 3698369, text = "No matter. We will find what we seek in another." },
            { id = 2108692, text = "No! My eyes! It burns!" },
            { id = 561240, text = "No! We are a force even more terrifying!" },
            { id = 2736331, text = "No. He did. And so did you." },
            { id = 1245013, text = "No. The Forsaken will never stop fighting." },
            { id = 3049151, text = "Nothing lasts." },
            { id = 4496039, text = "Now the work begins." },
            { id = 4383683, text = "of Tyrande Whisperwind." },
            { id = 1248858, text = "One shot, one kill." },
            { id = 3084073, text = "or worse." },
            { id = 2002711, text = "Our encampment is secure for now, but remain vigilant." },
            { id = 4325055, text = "Our only hope is that Anduin's will proves stronger." },
            { id = 2002783, text = "Our success in this conflict may depend on your skills." },
            { id = 1801005, text = "Our true work is just beginning." },
            { id = 2108694, text = "Pass through the wall, quickly! I cannot hold it much longer!" },
            { id = 2002721, text = "Poor thing. She barely got a chance to swing." },
            { id = 1248695, text = "Pull Bane back to my position! Close ranks!" },
            { id = 2108678, text = "Regret nothing. You did well." },
            { id = 2736334, text = "Remember your loyalties." },
            { id = 1248864, text = "Right to the face!" },
            { id = 2108698, text = "Saurfang, it's about time." },
            { id = 2002759, text = "Saurfang, where did you go?" },
            { id = 2029158, text = "See it done, and dispatch reports of your progress to me." },
            { id = 897342, text = "She's attacking the towers again!" },
            { id = 5225424, text = "Shurele-Oram, my friend." },
            { id = 2002766, text = "So good of you to finally show up, High Overlord." },
            { id = 2429532, text = "so he can slaughter them in their sleep." },
            { id = 2108688, text = "Soldiers, no! Do not rush the-" },
            { id = 1801001, text = "State your business to your Warchief." },
            { id = 3698368, text = "Such a narrow vision. You disappoint me." },
            { id = 561222, text = "Taranis had a son named Arthas." },
            { id = 2736330, text = "Thank you for your honesty." },
            { id = 4327514, text = "That is yet to come." },
            { id = 2002720, text = "That night elf commander is testing my patience. Break her!" },
            { id = 2108674, text = "That ship must have come from Darnassus, which means..." },
            { id = 2002738, text = "That should quell their appetites. For a while, at least." },
            { id = 1243488, text = "The Alliance will be upon us soon, and we have nowhere to run." },
            { id = 4093251, text = "The archer does not mourn the loss of their arrows, high lord." },
            { id = 4075661, text = "The battle is almost upon us." },
            { id = 4322888, text = "The cycle must be broken." },
            { id = 4324001, text = "The jailer did not control me." },
            { id = 4324764, text = "The jailer is using Anduin to bolster his ranks!" },
            { id = 1801000, text = "The lifeblood of Azeroth belongs to the Horde." },
            { id = 4081168, text = "The Maw devours everything!" },
            { id = 4081169, text = "The Maw will claim you!" },
            { id = 4081161, text = "The past shackles you!" },
            { id = 4322891, text = "The true battle lies ahead." },
            { id = 1248735, text = "There are so many of them!" },
            { id = 2429533, text = "There can only be victory or death for us, Spain." },
            { id = 2736333, text = "There is no place for weakness in our ranks." },
            { id = 2108686, text = "There will be nowhere to run when next we meet, Malfurion." },
            { id = 3084079, text = "They will learn the truth along with all the rest." },
            { id = 4080418, text = "This ends now." },
            { id = 2002752, text = "This is no time for sentiment, High Overlord!" },
            { id = 573172, text = "This isn't how it's supposed to end." },
            { id = 4080414, text = "To the skies, strike at the heart!" },
            { id = 561226, text = "To those who would question our place in this world!" },
            { id = 2108669, text = "To Zorumgar! Quickly!" },
            { id = 4081774, text = "Vengeance is mine!" },
            { id = 561263, text = "Very well, Warchief. I have solved the plight of the Forsaken." },
            { id = 4081777, text = "Very well. Death it is!" },
            { id = 1248709, text = "Vol'jin! Pull him back! Keep your lines steady! We have to hold!" },
            { id = 2002753, text = "War demands that we take a more direct approach." },
            { id = 561229, text = "Warchief! So glad you could make it!" },
            { id = 2108696, text = "We advance as the fires continue to burn." },
            { id = 4322895, text = "We live in prisms of our own making." },
            { id = 2108682, text = "We must stay the course for now." },
            { id = 2120267, text = "We pass through the wall on my command!" },
            { id = 561258, text = "We watched as our homes were razed to the ground." },
            { id = 1800996, text = "We will bring the Alliance to its knees." },
            { id = 1800999, text = "We will claim what is ours." },
            { id = 2108663, text = "We will squeeze Malfurion from both sides." },
            { id = 1248866, text = "We'll never bow to you!" },
            { id = 1248672, text = "We'll take the ridge and cover your flank." },
            { id = 4080410, text = "Well?" },
            { id = 2002765, text = "We're almost there! Make haste, heroes!" },
            { id = 1244135, text = "What have we here? Another one of Greymane's mercenaries?" },
            { id = 1782211, text = "What have you to say, Chieftain?" },
            { id = 1993353, text = "What say you, champion? Are you prepared to pursue a new ally?" },
            { id = 2108702, text = "When I sent you on this mission, I did not foresee this outcome." },
            { id = 2108693, text = "Where did you fly away to, little bird?" },
            { id = 561269, text = "Where is that ogre-headed buffoon?" },
            { id = 4496030, text = "Why are you here, Andwan?" },
            { id = 2108681, text = "Wildbend River is locked in a stalemate, and Malfurion knows it." },
            { id = 2575609, text = "Yes, it is beyond time we did." },
            { id = 897346, text = "You do realize we are directly below it, right?" },
            { id = 4496034, text = "You fear you might not be who you thought you were." },
            { id = 2429536, text = "You should be grateful." },
            { id = 2068242, text = "You were the right arrow for the shot, champion." },
            { id = 4081138, text = "Your lives end here!" },
            { id = 3587735, text = "Your skills come highly recommended. I will make use of them." },
            { id = 2736329, text = "Zelling." },
            { id = 4081165, text = "Zovaal will not be denied!" },
        } },
    } },
