-- The order families and the groups inside them are offered in, emitted
-- here so the panel does not re-derive it and disagree with this file.
GameVoices.FAMILY_ORDER = {
    "Fighting",
    "Hurt and dying",
    "Orders and warnings",
    "Manners",
    "Fun",
    "Menace",
    "Feelings",
    "Other",
}
GameVoices.GROUP_ORDER = {
    "Battle cries",
    "Battle roars",
    "Attack grunts",
    "Casting",
    "Threats",
    "Boasts",
    "Mockery",
    "Orders",
    "Warnings",
    "Calls for aid",
    "Running dry",
    "Victory",
    "Pain",
    "Death cries",
    "Stunned",
    "Falling in battle",
    "Greetings",
    "Farewells",
    "Yes and no",
    "Courtesies",
    "Congratulations",
    "Jokes",
